True def transform(grid):
    g=[row[:] for row in grid]
    R,C=len(g),len(g[0])
    centers=[]
    # detect monochrome 3x3 squares
    for r in range(R-2):
        for c in range(C-2):
            v=g[r][c]
            if v and all(g[i][j]==v for i in range(r,r+3) for j in range(c,c+3)):
                if not any((rr,cc,v)==(r,c,v) for rr,cc,v in centers): centers.append((r+1,c+1,v))
    rays={}
    for r,c,v in centers:
        for j in range(C): rays[(r,j)]=v
        for i in range(R): rays[(i,c)]=v
    # At intersections of rays from different blocks, leave blank.
    for (i,j),v in rays.items():
        vals={w for rr,cc,w in centers if (i==rr or j==cc)}
        if len(vals)>1: g[i][j]=0
        else: g[i][j]=v
    return g
